{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C09"],
      "claim": "In rats, praziquantel, a close amide-containing analogue, reached brain concentrations of 5.7 µg/g within 5 min after i.v. dosing, directly demonstrating BBB permeation.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "PRE-084, a morpholinoethyl ester with a piperidine-like amine, was rapidly distributed to mouse brain (773.6 ng/g at Tmax) with concurrent spinal cord and plasma exposure, supporting meaningful CNS access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "The piperidine-containing radiotracer BMP showed extremely high brain uptake (>14% ID/g in all brain regions) at 2 min in mice, directly demonstrating that a piperidine aromatic ester/amide scaffold can cross the BBB.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Sesamol, which contains the same 1,3-benzodioxole ring as the query, crosses the BBB and reaches brain tissue, indicating that the benzodioxole motif is compatible with CNS penetration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "A radioligand containing an aryl dioxole-like motif and piperazine/piperidine elements showed extremely high mouse brain uptake with no brain metabolites, supporting robust CNS access for this compound class.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "Pass. Multiple highly transferable in vivo CNS exposure measurements in rats and mice support meaningful BBB access for this amide/piperidine/benzodioxole scaffold. The query's favorable physicochemical profile (MW 233, logD 2.04, TPSA 38.8, no HBD, neutral) is consistent with passive diffusion and does not contradict the experimental evidence.",
  "evidence_gaps": [
    "No direct brain/plasma or CSF measurement for the exact query molecule; inference relies on highly transferable analogues.",
    "No explicit P-gp/BCRP efflux assay for the query; however, the neutral, low-TPSA, low-MW profile and analogue data do not suggest a major efflux liability."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

